import axios from 'axios';

async function downloadUserImages(username: string, apiKey: string) {
  const baseUrl = 'https://civitai.com/api/v1/images';
  const params = {
    username: username,
    limit: 0, // Request all images
    apiKey: apiKey
  };

  const response = await axios.get(baseUrl, { params: params });
  const images = response.data.items;

  for (const image of images) {
    const imageUrl = image.url;
    const filename = image.id + '.jpg'; // Assuming jpg file extension
    await axios.get(imageUrl, { responseType: 'stream' }).then((response) => {
      response.data.pipe(fs.createWriteStream(filename));
    });
  }
}

// Usage
const username = 'deniskropp';
const apiKey = '0be1d17f909493be1aa3b7f9224728f2';
downloadUserImages(username, apiKey);
```

This function makes use of the Axios library to perform HTTP requests. It constructs the appropriate endpoint URL with query parameters to fetch all images created by the user 'deniskropp'. The API key is included as a query parameter to authenticate the request.

The function then iterates through the returned images and constructs the image URLs. It downloads each image using Axios with the `responseType` set to `'stream'` to handle the binary data. The image data is piped to a file stream to save the image locally.

Note that this code assumes the presence of the `fs` module for writing files. Also, ensure that you have the necessary permissions and file system access to perform the image downloads and save them locally.
